class Node:
    def __init__(self, val):
        self.val = val
        self.next = None

class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def prepend(self, val):          # O(1)
        node = Node(val)
        node.next = self.head
        self.head = node

    def delete_after(self, node):   # O(1) given the predecessor
        node.next = node.next.next
